private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    //define the boolean variable to track whether the character was decoded or not
    boolean decoded = false;
    // Initialize a variable to store the number of bytes read
    int numBytes = 0;
    // Loop until the character is decoded or the buffer is depleted
    while (! decoded && i < bb.limit()) {
        // Read the next byte and store its value
        int b = bb.get(i++);
        // Check if the byte is a single-byte character
        if ((b & 0x80) == 0) {
            // Add the byte to the string buffer
            sb.append((char) b);
            // Increment the index by 1
            i++;
            // Mark the character as decoded
            decoded = true;
        }
        else if ((b & 0xE0) == 0xC0) {
            // The byte is the first byte of an UTF-8 multi-byte sequence
            // Read the second byte and store its value
            int b1 = bb.get(i++);
            // Check if the second byte is valid
            if ((b1 & 0xC0) != 0x80) {
                // Throw an exception if the second byte is not valid
                throw new UTFDataFormatException("Invalid UTF-8 sequence");
            }
            // Get the number of bytes in the sequence
            numBytes = getNumBytes(b);
            // Check if the buffer has enough bytes to read
            if (i + numBytes > bb.limit()) {
                // Throw an exception if the buffer is depleted
                throw new UTFDataFormatException("Incomplete UTF-8 sequence");
            }
            // Read the remaining bytes
            for (int j = 0; j < numBytes; j++) {
                bb.get(i++);
            }
            // Convert the bytes into a character
            char c = (char) (b << (6 * (numBytes - 1)));
            // Add the character to the string buffer
            sb.append(c);
            // Increment the index by the number of read bytes
            i += numBytes;
            // Mark the character as decoded
            decoded = true;
        }
        else {
            // Throw an exception for any other byte
            throw new UTFDataFormatException("Invalid starting byte");
        }
    }
    // Return the next unchecked character in the string to decode
    return i;
}

