private static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the year and month from the time bucket
    int year = (int) (timeBucket / 100000000);
    int month = (int) ((timeBucket / 1000000) % 100);

    // Calculate the day and hour from the time bucket
    int day = (int) ((timeBucket / 10000) % 100);
    int hour = (int) ((timeBucket / 100) % 100);

    // Calculate the new year and month based on the day step
    if (dayStep == 0) {
      // If day step is 0, keep the current year and month
      year = year;
      month = month;
    } else if (dayStep > 0) {
      // If day step is positive, add the day step to the month
      month += dayStep;
      if (month > 12) {
        // If the month is greater than 12, subtract 12 from the month and add 1 to the year
        year++;
        month -= 12;
      }
    } else {
      // If day step is negative, subtract the day step from the month
      month -= dayStep;
      if (month < 1) {
        // If the month is less than 1, subtract 1 from the month and add 1 to the year
        year--;
        month += 12;
      }
    }

    // Calculate the new day and hour based on the day step
    if (dayStep == 0) {
      // If day step is 0, keep the current day and hour
      day = day;
      hour = hour;
    } else if (dayStep > 0) {
      // If day step is positive, add the day step to the day
      day += dayStep;
      if (day > 31) {
        // If the day is greater than 31, set the day to 31
        day = 31;
      }
    } else {
      // If day step is negative, subtract the day step from the day
      day -= dayStep;
      if (day < 1) {
        // If the day is less than 1, set the day to 1
        day = 1;
      }
    }

    // Return the new time bucket
    return year * 100000000 + month * 1000000 + day * 10000 + hour * 100;
  }

