public static void writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.writeByte((byte) c);
        } else if (c < 0x800) {
            lb.writeByte((byte)(0xc0 | (c >> 6)), 0x80 | (c & 0x3f));
        } else if (c < 0xd800 || c >= 0xe000) {
            lb.writeByte((byte)(0xe0 | (c >> 12)), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
        } else {
            // surrogate pair
            ++i;
            char c2 = str.charAt(i);
            int u = (c & 0x3ff) << 10 | (c2 & 0x3ff);
            lb.writeByte((byte)(0xf0 | (u >> 18)), 0x80 | ((u >> 12) & 0x3f), 0x80 | ((u >> 6) & 0x3f), 0x80 | (u & 0x3f));
        }
    }
