public static int nextPrime(int desiredCapacity) {
    // Handle the case where the desired capacity is 0 or negative
    if (desiredCapacity <= 0) {
        return 1;
    }

    // Handle the case where the desired capacity is 1 or 2
    if (desiredCapacity <= 2) {
        return desiredCapacity;
    }

    // Otherwise, round up the desired capacity to the next largest multiple of 2
    int roundedDesiredCapacity = (desiredCapacity + 1) & (~1);

    // Check if the rounded capacity is prime
    boolean isPrime = true;
    for (int i = 2; i < roundedDesiredCapacity; i++) {
        if (roundedDesiredCapacity % i == 0) {
            isPrime = false;
            break;
        }
    }

    if (isPrime) {
        return roundedDesiredCapacity;
    } else {
        // If the rounded capacity is not prime, find the next prime number greater than it
        for (int i = roundedDesiredCapacity + 1; i < Integer.MAX_VALUE; i++) {
            if (i % 2 != 0 && i % 3 != 0 && i % 5 != 0 && i % 7 != 0) {
                return i;
            }
        }
    }

    return -1;
}
