int removeUnusedNodes() {
    // Iterate over all nodes in the Category tree
    for (Node node : tree) {
        // Check if the node is active
        if (!node.isActive()) {
            // Remove the node and its children
            tree.remove(node);
            for (Node child : node.getChildren()) {
                tree.remove(child);
            }
        }
    }

    // Return the number of removed nodes
    return tree.size();
}
