public int removeUnusedNodes() {
    int count = 0;

    // Find the first inactive node
    CategoryNode current = getRootNode();
    while (current != null && !current.isActive()) {
        current = current.getChild(0);
    }

    // Remove inactive nodes
    while (current != null) {
        count++;
        current = current.getParent();
        current.removeChild(current.getChild(0));
        current = current.getChild(0);
    }

    return count;
}

