public int removeUnusedNodes() {
    int removedNodes = 0;
    for (int i = tree.size() - 1; i >= 0; i--) {
        if (!tree.get(i).isActive()) {
            removedNodes++;
            tree.remove(i);
        }
    }
    return removedNodes;
}
