    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IllegalArgumentException("Invalid offset: " + byteOffset);
    }

    if (byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IllegalArgumentException("Invalid length: " + byteLength);
    }

    for (int i = 0; i < byteLength; i++) {
        this.add(byteArrayValue[byteOffset + i]);
    }

