private MatchResult match(CharSequence uri) {
    int patternLength = pattern.length();
    int uriLength = uri.length();

    // Check that the URI is long enough to match the pattern
    if (uriLength < patternLength) {
        return null;
    }

    // Compare the elements of the pattern to the corresponding elements of the URI
    for (int i = 0; i < patternLength; i++) {
