public boolean isCompatible(DataTable dataset) {
    // Check if the dataset has the same number of columns as this bucket
    if (dataset.getColumnCount() != this.getColumnCount()) {
        return false;
    }

    // Check if the dataset has the same column names as this bucket
    for (int i = 0; i < this.getColumnCount(); i++) {
        if (!this.getColumnName(i).equals(dataset.getColumnName(i))) {
            return false;
        }
    }

    // Check if the dataset has the same data type as this bucket for each column
    for (int i = 0; i < this.getColumnCount(); i++) {
        if (this.getColumnType(i) != dataset.getColumnType(i)) {
            return false;
        }
    }

    // If all checks pass, the buckets are compatible
    return true;
}
