private List<Pair<Integer, Integer>> computeMinimalSeparators(E edge) {
    // Initialize the list of minimal separators
    List<Pair<Integer, Integer>> separators = new ArrayList<>();

    // Get the two endpoints of the edge
    int v1 = graph.getEdgeSource(edge);
    int v2 = graph.getEdgeTarget(edge);

    // Iterate over all vertices in the graph
    for (int vertex : graph.vertexSet()) {

        // Ignore the two endpoints of the edge
        if (vertex == v1 || vertex == v2) continue;

        // If the vertex is not connected to the edge, add a separator
        if (!graph.containsEdge(vertex, v1) && !graph.containsEdge(vertex, v2)) {
            separators.add(new Pair<>(vertex, edge));
        }
    }

    // Return the list of minimal separators
    return separators;
}

