private List<Pair<Integer, Integer>> computeSeparators(E e) {
    // Initialize the list of separators
    List<Pair<Integer, Integer>> separators = new List<>();

    // Get the neighbors of the current edge
    Set<Integer> neighbors = graph.neighborSet(e);

    // Iterate over all neighbors of the current edge
    for (Integer neighbor : neighbors) {
        // Get the neighbors of the current neighbor
        Set<Integer> neighborNeighbors = graph.neighborSet(neighbor);

        // Compute the separator between the current edge and the current neighbor
        Pair<Integer, Integer> separator = computeSeparator(e, neighbor, neighborNeighbors);

        // Add the separator to the list of separators
        separators.add(separator);
    }

    return separators;
}

// Compute the separator between the given edge and the given neighbor
private Pair<Integer, Integer> computeSeparator(E e, Integer neighbor, Set<Integer> neighborNeighbors) {
    // Get the neighbors of the current edge
    Set<Integer> edgeNeighbors = graph.neighborSet(e);

    // Find the common neighbor between the edge and the neighbor
    Integer commonNeighbor = findCommonNeighbor(edgeNeighbors, neighborNeighbors);

    // If there is no common neighbor, return an empty separator
    if (commonNeighbor == null) {
        return new Pair<>(null, null);
    }

    // Compute the separator between the edge and the neighbor
    return new Pair<>(commonNeighbor, neighbor);
}

