private Integer findCommonNeighbor(Set<Integer> set1, Set<Integer> set2) {
    // Iterate over the first set of neighbors
    for (Integer element : set1) {
        // Check if the element is in the second set of neighbors
        if (set2.contains(element)) {
            // If the element is in the second set of neighbors, return it as the common neighbor
            return element;
        }
    }

    // If no common neighbor is found, return null
    return null;
}
