public void pop(String descriptor) {
if (descriptor.contains("(")) {
// It is a method descriptor.
int i = 0;
ArrayList<String> argumentTypes = new ArrayList<>();
// Iterate through the characters in the descriptor and find the argument types.
for (i = 0; i < descriptor.length(); i++) {
char c = descriptor.charAt(i);
if (c == ')') {
break;
} else if (c == 'L') {
StringBuilder argType = new StringBuilder();
while (descriptor.charAt(i) != ';') {
argType.append(descriptor.charAt(i));
i++;
}
// We have found a class type.
argumentTypes.add(argType.toString());
i++;
break;
}
}
// Pop the argument types from the output frame.
ArrayList<Frame> poppedFrames = new ArrayList<>();
for (String argType : argumentTypes) {
if (argType.equals("I")) {
poppedFrames.add(Frame.createIntegerReference());
